// Simple canvas game targeting <canvas id="game"></canvas>
// Arrow keys move a circle within the canvas bounds.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // canvas not found
  const ctx = canvas.getContext('2d');
  // Set canvas size to fill its container or default size
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  const state = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    radius: 20,
    speed: 4,
    dx: 0,
    dy: 0,
  };

  const keys = {
    ArrowUp: false,
    ArrowDown: false,
    ArrowLeft: false,
    ArrowRight: false,
  };

  // Handle keyboard input
  window.addEventListener('keydown', (e) => {
    if (e.key in keys) {
      keys[e.key] = true;
      e.preventDefault();
    }
  });
  window.addEventListener('keyup', (e) => {
    if (e.key in keys) {
      keys[e.key] = false;
      e.preventDefault();
    }
  });

  function update() {
    // Update velocity based on pressed keys
    state.dx = 0;
    state.dy = 0;
    if (keys.ArrowUp) state.dy = -state.speed;
    if (keys.ArrowDown) state.dy = state.speed;
    if (keys.ArrowLeft) state.dx = -state.speed;
    if (keys.ArrowRight) state.dx = state.speed;

    // Update position
    state.x += state.dx;
    state.y += state.dy;

    // Keep inside bounds
    if (state.x - state.radius < 0) state.x = state.radius;
    if (state.x + state.radius > canvas.width) state.x = canvas.width - state.radius;
    if (state.y - state.radius < 0) state.y = state.radius;
    if (state.y + state.radius > canvas.height) state.y = canvas.height - state.radius;
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#3498db';
    ctx.beginPath();
    ctx.arc(state.x, state.y, state.radius, 0, Math.PI * 2);
    ctx.fill();
  }

  function loop() {
    update();
    draw();
    requestAnimationFrame(loop);
  }

  // Start the game loop
  requestAnimationFrame(loop);
})();
